mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text FROM PTL_PORTFOLIO A LEFT JOIN PTL_SEC_ACCT PSA ON A.PORTFOLIO_ID = PSA.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO PCI ON PCI.PORTFOLIO_ID = A.PORTFOLIO_ID and PCI.ACCT_TYPE = 'A01' WHERE A.INVEST_YESORNO = 'Y' AND A.PORTFOLIO_ID != #{invTransPortf,jdbcType=VARCHAR} AND A.MDATE >=TO_DATE(#{tradeDate},'yyyy-MM-dd') AND A.VDATE <=TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND PSA.ACCT_NO=#{secAcctId,jdbcType=VARCHAR}
AND A.PORTFOLIO_ID = #{initValue}
AND (A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR A.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND ( A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT DISTINCT NVL(SUM(NVL(AMOUNT, 0)),0)
   FROM PTL_SEC_POSITION_FLOW
   WHERE HODING_TYPE = '01'
   AND CDATE = TO_DATE(#{searchDate},'yyyy-MM-dd')
   AND BRANCH = 0

       AND PORTFOLIO_ID = #{portfolioId}


       AND SEC_ACCT_ID = #{secAcctId}


       AND FINPROD_ID = #{finprodId}


       AND INV_AIM = #{invAim}


       AND CCY = #{ccy}
